          "act": 1,
          "title": "c. 2000 BC–AD 250: Mesoamerica’s Three Zones & Early Villages",
          "text": "<span class=\"para-ref\">[1.1]</span> Around **2000 BC**, farming families settled across **Mesoamerica** in warm Central America. Their homeland stretched from southern Mexico through Guatemala, Belize, Honduras, and El Salvador. Three contrasting zones traded precious goods along busy forest trails and winding rivers. In the southern **volcanic highlands**, workers dug sharp black **obsidian** glass and green **jade**. High in misty cloud forests, emerald **resplendent quetzal** birds flashed tail feathers prized above gold.<br><br><span class=\"para-ref\">[1.2]</span> Farther north lay the hot central **rainforest lowlands**, where jaguars prowled and scarlet macaws screeched. Beyond those jungles stretched the flat **Yucatán Peninsula**, resting on pale porous **limestone** rock. Gradually, small farming villages grew into bustling stone cities without metal ploughs or wheeled carts!",
