          "text": "<span class=\"para-ref\">[1.3]</span> Long dry seasons tested Maya builders because rainwater sank straight through porous limestone ground. Families across Yucatán drew fresh water from deep natural limestone sinkholes called **cenotes**. At **Tikal**, engineers plastered huge stone reservoirs and underground **chultuns** to save rain. Farmers also dug raised **wetland fields** above swamps and carved stepped **terraces** onto hillsides.<br><br><span class=\"para-ref\">[1.4]</span> Clever **Three Sisters** companion planting fed tens of thousands of townspeople every single year. Tall **maize** stalks grew first, giving sturdy poles for climbing **beans** to twist up. Bean roots added richness back into soil, while wide **squash** leaves shaded damp earth. Prickly squash stems also kept raccoons away and stopped weeds choking young crops!",
