          "title": "c. AD 600–900: Stone Rainforest Cities vs Anglo-Saxon Britain",
          "text": "<span class=\"para-ref\">[1.5]</span> Ordinary Maya families built cool palm-thatched homes with whitewashed limestone walls around sunny shared courtyards. Downtown at **Uxmal** and **Tikal**, masons stacked pale limestone blocks into towering **step-pyramids**. Bright plazas hosted noisy markets trading cacao beans, woven cotton, salt, flint blades, and honey.<br><br><span class=\"para-ref\">[1.6]</span> Compare that busy world with **Anglo-Saxon Britain** around **AD 900**, far across the Atlantic Ocean! Most people in Britain lived in small timber villages and farmed with iron-tipped ploughs. Anglo-Saxon kings ruled wooden halls, whereas Maya cities gleamed with painted plazas, observatories, and carved monuments!",
