          "model_answer": "Looking closely at Sources A, B, and C, historians can see how cleverly Maya families lived because Source A shows sacred multi-coloured maize, which could be dried and ground to feed whole cities. Source B reveals how Three Sisters companion planting grew tall maize as bean poles, climbing beans to enrich the soil, and prickly squash leaves to trap moisture. Finally, Source C shows how whitewashed limestone walls and steep palm-thatch roofs kept family courtyards cool and dry through tropical storms!",
