          "text": "<span class=\"para-ref\">[2.1]</span> From **AD 250 to 900**, the Classic Maya never formed one single united empire. Like Ancient Greece, over forty independent **city-states** competed for land, trade, and royal glory. Rival powers like **Tikal**, **Calakmul**, **Palenque**, **Copán**, and **Yaxchilán** forged alliances and fought wars. Each city-state obeyed its own sacred ruler called the **K'uhul Ajaw**, meaning holy lord.<br><br><span class=\"para-ref\">[2.2]</span> People believed the **Ajaw** spoke with the gods to bring gentle rain and rich harvests. On festival days, rulers stood high atop steep limestone **step-pyramids** above crowded plazas. Narrow stone temple rooms crowned each pyramid beneath overlapping **corbelled vaults** and bright red stucco.",
