          "model_answer": "Historians compare the Classic Maya world to Ancient Greece instead of one united empire because no single emperor ever ruled every Maya city at once. Instead, over forty independent city-states — including fierce rivals like Tikal and Calakmul alongside Palenque, Copán, and Yaxchilán — governed their own farmland and armies under a sacred K'uhul Ajaw. Even though they shared Maya gods, step-pyramids, and trade goods, rival city-states constantly formed alliances and competed for royal glory!",
