        "items": [
          {
            "stage": 1,
            "question": "What were the plastered bottle-shaped underground chambers built by Maya engineers to store rainwater called?",
            "answer": "Chultuns",
            "explanation": "Alongside giant stone reservoirs and natural cenote sinkholes, plastered chultuns kept cities supplied through dry months!"
          },
          {
            "stage": 1,
            "question": "Why did planting broad-leaved squash beside maize and beans help Maya fields thrive?",
            "answer": "Wide prickly squash leaves shaded the soil to lock in moisture and block weeds",
            "explanation": "Together, maize, climbing beans, and squash formed the nourishing Three Sisters farming team."
          },
          {
            "stage": 2,
            "question": "Why do historians compare the Classic Maya to Ancient Greece rather than one united empire?",
            "answer": "Because the Maya lived in over forty independent rival city-states such as Tikal, Calakmul, and Palenque",
            "explanation": "Each Maya city-state had its own sacred K'uhul Ajaw (\"holy lord\"), laws, and alliances."
          },
          {
            "stage": 2,
            "question": "Where was King Pakal the Great buried in AD 683, and what famous treasure covered his face?",
            "answer": "Beneath the Temple of the Inscriptions at Palenque, wearing a green jade mosaic funerary mask",
            "explanation": "Pakal ascended Palenque’s throne aged twelve in AD 615 and ruled for sixty-eight years!"
          },
          {
            "stage": 3,
            "question": "Name two powerful royal Maya women remembered on Classic stone carvings.",
            "answer": "Lady Sak K'uk' of Palenque and Lady Six Sky of Naranjo",
            "explanation": "Lady Sak K'uk' crowned young Pakal, while Lady Six Sky rebuilt Naranjo and stood victorious on royal stelae!"
          }
        ]
