          "model_answer": "Maya mathematicians achieved one of world history’s greatest breakthroughs because they independently invented place-value zero long before Europe used it! While Britain and Rome still used Roman numerals with no zero, Maya scholars built a clever base-20 system using just three symbols: a shell for zero, a pebble dot for one, and a wooden bar for five. Stacking numbers vertically in columns of ones, twenties, and four hundreds let market traders tally thousands of cacao beans and helped astronomers calculate sky cycles across centuries!",
