          "text": "<span class=\"para-ref\">[5.1]</span> Sacred Maya stories survived in a K'iche' creation book called the **Popol Vuh**. First, the gods tried shaping humans from wet mud, yet they crumbled in rain. Next, carved wooden people walked and talked, yet forgot to thank their makers! Finally, the gods kneaded yellow and white **maize dough** to create grateful human beings.<br><br><span class=\"para-ref\">[5.2]</span> In another famous tale, the **Hero Twins** beat the dark lords of **Xibalba** at **Pok-ta-Pok**! Their victory helped the **Maize God** rise again like green corn sprouting from dark earth. Maya families believed deep limestone caves and **cenotes** were real doorways into watery Xibalba. Priests entered cool caves burning sweet **copal** resin and offering gifts to rain god **Chaac**.",
