            "stage": 3,
            "question": "How did Chichén Itzá’s builders design El Castillo to honour Kukulkan and track the 365-day solar year?",
            "answer": "Four staircases of 91 steps plus 1 top platform equal 365 days, casting a sunlit serpent shadow every spring and autumn equinox",
            "explanation": "Architecture and astronomy worked together so crowds could watch Kukulkan’s shadow signal spring rains and autumn harvest."
