          "image": "/units/ks2_maya_civilisation/assets/tulum_cliffside_coastal_maya_temple.jpg",
          "image_alt": "Walled Postclassic Maya stone temple of Tulum perched on rocky cliffs above turquoise Caribbean waves",
          "caption": "Cliffside Maya port of Tulum on the Caribbean coast — still bustling with sea-canoe merchants centuries after AD 900!",
          "image_caption": "Cliffside Maya port of Tulum on the Caribbean coast — still bustling with sea-canoe merchants centuries after AD 900!",
